"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Asset, Space, Activity as ActivityType, User } from "@/lib/generated/prisma/client";
import { QRCodeSVG } from "qrcode.react";
import { ArrowLeft, Edit, MoreVertical, PackageOpen, FileText, Wrench, Activity, Tag, Share2, Info, FileStack, Banknote } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Timeline, TimelineItem } from "@/components/ui/timeline";
import { ConnectedHomeGraph, GraphNode } from "@/components/graph/connected-home-graph";
import { useRecentStore } from "@/store/recent-store";
import { useEffect } from "react";

type AssetWithRelations = Asset & {
  space: Space | null;
  createdBy: User | null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  documents?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  maintenance?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  expenses?: any[];
};

interface AssetDetailClientProps {
  asset: AssetWithRelations;
  activities: ActivityType[];
  relationshipsPanel?: React.ReactNode;
}

export function AssetDetailClient({ asset, activities, relationshipsPanel }: AssetDetailClientProps) {
  const [activeTab, setActiveTab] = useState("passport");
  const addRecent = useRecentStore((state) => state.addRecent);

  useEffect(() => {
    addRecent({
      id: asset.id,
      title: asset.name,
      type: "asset",
      url: `/assets/${asset.id}`
    });
  }, [asset.id, asset.name, addRecent]);

  const qrUrl = typeof window !== "undefined" ? `${window.location.origin}/assets/${asset.id}` : "";

  // Deterministic Health Calculation
  const hasPhoto = !!asset.coverImage;
  const hasPurchaseDetails = !!asset.purchaseDate && !!asset.purchasePrice;
  const hasIdentity = !!asset.brand || !!asset.model || !!asset.serialNumber;
  const isCategorized = !!asset.category;

  let healthScore = 0;
  if (hasPhoto) healthScore += 25;
  if (hasPurchaseDetails) healthScore += 25;
  if (hasIdentity) healthScore += 25;
  if (isCategorized) healthScore += 25;

  const isLearning = healthScore < 100;

  const healthColor = asset.condition === "NEW" || asset.condition === "EXCELLENT" 
    ? "bg-forest/10 text-forest" 
    : asset.condition === "GOOD" 
    ? "bg-amber-500/10 text-amber-600" 
    : "bg-terracotta/10 text-terracotta";

  const documents = asset.documents || [];
  const maintenance = asset.maintenance || [];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const upcomingService = maintenance.find((m: any) => m.status === "SCHEDULED" && new Date(m.scheduledDate) >= new Date());
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const lastMaintenance = [...maintenance].reverse().find((m: any) => m.status === "COMPLETED");

  const expenses = asset.expenses || [];
  const totalPurchaseCost = asset.purchasePrice || 0;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const maintenanceExpenses = expenses.reduce((sum: number, exp: any) => sum + exp.amount, 0);
  const totalInvestment = totalPurchaseCost + maintenanceExpenses;

  // Connected Home Graph Data
  const centralNode: GraphNode = {
    id: asset.id,
    type: "ASSET",
    name: asset.name,
    subtitle: asset.brand || asset.category,
    link: `/assets/${asset.id}`
  };

  const satellites: GraphNode[] = [];
  if (asset.space) {
    satellites.push({
      id: asset.space.id,
      type: "SPACE",
      name: asset.space.name,
      subtitle: "Located In",
      link: `/spaces/${asset.space.id}`
    });
  }
  if (asset.createdBy) {
    satellites.push({
      id: asset.createdBy.id,
      type: "MEMBER",
      name: asset.createdBy.name || "Unknown",
      subtitle: "Added By",
      link: `/family/${asset.createdBy.id}`
    });
  }
  documents.forEach((doc: any) => satellites.push({
    id: doc.id,
    type: "DOCUMENT",
    name: doc.title,
    link: `/vault/${doc.id}`
  }));
  maintenance.forEach((m: any) => satellites.push({
    id: m.id,
    type: "MAINTENANCE",
    name: m.title,
    link: `/care/${m.id}`
  }));
  expenses.forEach((e: any) => satellites.push({
    id: e.id,
    type: "EXPENSE",
    name: e.title,
    subtitle: `${e.currency} ${e.amount}`,
    link: `/money/${e.id}`
  }));

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-10 pb-24">
      {/* Navigation */}
      <div className="flex items-center gap-4">
        <Link href="/assets" className="p-2 rounded-full hover:bg-secondary/60 transition-colors">
          <ArrowLeft className="h-5 w-5 text-muted-foreground" />
        </Link>
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Link href="/assets" className="hover:text-foreground transition-colors">Assets</Link>
          <span>/</span>
          <span className="text-foreground font-medium truncate">{asset.name}</span>
        </div>
      </div>

      {/* Hero Header */}
      <div className="bg-card/40 backdrop-blur-md border border-border/50 rounded-[2.5rem] overflow-hidden flex flex-col md:flex-row relative">
        <div className="md:w-1/3 bg-secondary/30 flex items-center justify-center min-h-[300px] relative overflow-hidden group">
          {asset.coverImage ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={asset.coverImage} alt={asset.name} className="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 ease-out" />
          ) : (
            <div className="absolute inset-0 bg-gradient-to-tr from-primary/10 via-background to-secondary flex items-center justify-center group-hover:scale-105 transition-transform duration-700">
              <PackageOpen className="h-20 w-20 text-muted-foreground/30 stroke-[1]" />
            </div>
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
        </div>

        <div className="md:w-2/3 p-8 md:p-10 flex flex-col justify-between">
          <div>
            <div className="flex justify-between items-start gap-4 mb-4">
              <div className="flex flex-wrap items-center gap-2">
                <span className="px-3 py-1 bg-secondary rounded-full text-[10px] font-bold tracking-widest uppercase text-muted-foreground">
                  {asset.category || "Uncategorized"}
                </span>
                <span className={cn("px-3 py-1 rounded-full text-[10px] font-bold tracking-widest uppercase", healthColor)}>
                  {asset.condition}
                </span>
              </div>
              <div className="flex gap-2 items-center">
                <Link href={`/home/timeline?targetId=${asset.id}&targetType=ASSET`}>
                  <Button variant="outline" size="sm" className="rounded-full h-10 text-xs font-bold tracking-widest uppercase text-muted-foreground hover:text-foreground">
                    History
                  </Button>
                </Link>
                <Button aria-label="Edit asset" variant="outline" size="icon" className="rounded-full h-10 w-10">
                  <Edit className="h-4 w-4" />
                </Button>
                <Button aria-label="More options" variant="outline" size="icon" className="rounded-full h-10 w-10">
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </div>
            </div>

            <h1 className="text-4xl md:text-5xl font-serif tracking-tight text-primary leading-tight">{asset.name}</h1>
            <p className="text-lg text-muted-foreground mt-2 font-light flex items-center gap-2">
               {asset.space?.name || "Unassigned Space"} 
               <span className="text-muted-foreground/30">•</span>
               {asset.brand || "Unknown Brand"}
            </p>
          </div>

          <div className="mt-10 pt-6 border-t border-border/40 grid grid-cols-2 md:grid-cols-4 gap-6">
            <div>
              <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Status</p>
              <p className="font-medium text-sm">{asset.status}</p>
            </div>
            <div>
              <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Added By</p>
              <p className="font-medium text-sm truncate">{asset.createdBy?.name || "System"}</p>
            </div>
            <div>
              <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Added Date</p>
              <p className="font-medium text-sm">{new Date(asset.createdAt).toLocaleDateString()}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Connected Home Section */}
      <section className="space-y-6 pt-6">
        <h2 className="text-xl font-serif tracking-tight text-primary">Connected Home</h2>
        <ConnectedHomeGraph centralNode={centralNode} satellites={satellites} />
      </section>

      {/* Main Content Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Left Column - Deep Passport */}
        <div className="lg:col-span-8 space-y-10">

          <div className="flex gap-4 border-b border-border/50 pb-px overflow-x-auto scrollbar-none">
            <button
              onClick={() => setActiveTab("passport")}
              className={cn("px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap", activeTab === "passport" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground")}
            >
              Digital Passport
            </button>
            <button
              onClick={() => setActiveTab("timeline")}
              className={cn("px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap", activeTab === "timeline" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground")}
            >
              Activity Timeline
            </button>
          </div>

          <AnimatePresence mode="wait">
            {activeTab === "passport" && (
              <motion.div
                key="passport"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="space-y-10"
              >
                {/* Identity & Ownership */}
                <section>
                  <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-4">Identity & Ownership</h3>
                  <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 grid grid-cols-1 sm:grid-cols-2 gap-8">
                     <div>
                       <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Manufacturer / Brand</p>
                       <p className="font-medium">{asset.brand || asset.manufacturer || "Not specified"}</p>
                     </div>
                     <div>
                       <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Model Name / Number</p>
                       <p className="font-medium">{asset.model || "Not specified"}</p>
                     </div>
                     <div>
                       <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Serial Number</p>
                       <p className="font-mono text-sm">{asset.serialNumber || "Not specified"}</p>
                     </div>
                     <div>
                       <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Purchase Date</p>
                       <p className="font-medium">{asset.purchaseDate ? new Date(asset.purchaseDate).toLocaleDateString() : "Not specified"}</p>
                     </div>
                     <div>
                       <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Added By</p>
                       <p className="font-medium flex items-center gap-1.5">
                         {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                         {(asset.createdBy as any)?.name || "Unknown"}
                       </p>
                     </div>

                     {/* Dynamic Financial Overview */}
                     <div className="col-span-full grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
                       <div className="p-4 bg-background border border-border/50 rounded-2xl flex flex-col justify-center">
                         <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Purchase Cost</p>
                         <p className="text-xl font-serif">${totalPurchaseCost.toLocaleString()}</p>
                       </div>
                       <div className="p-4 bg-background border border-border/50 rounded-2xl flex flex-col justify-center">
                         <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Maintenance Cost</p>
                         <p className="text-xl font-serif">${maintenanceExpenses.toLocaleString()}</p>
                       </div>
                       <div className="p-4 bg-background border border-border/50 rounded-2xl flex flex-col justify-center bg-primary/5 border-primary/20">
                         <p className="text-[10px] font-bold tracking-widest uppercase text-primary mb-1">Total Investment</p>
                         <p className="text-xl font-serif text-primary">${totalInvestment.toLocaleString()}</p>
                       </div>
                       <div className="p-4 bg-background border border-border/50 rounded-2xl flex flex-col justify-center">
                         <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Est. Current Value</p>
                         <p className="text-xl font-serif">{asset.estimatedCurrentValue ? `$${asset.estimatedCurrentValue.toLocaleString()}` : "—"}</p>
                       </div>
                    </div>
                  </div>
                </section>

                {/* Vault & Documents Connection */}
                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Vault Documents</h3>
                    <Button variant="ghost" size="sm" className="h-8 text-xs font-medium text-primary">Upload Document</Button>
                  </div>
                  <div className="bg-transparent border border-dashed border-border/60 rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                    {documents.length > 0 ? (
                      <div className="text-left w-full space-y-3">
                         {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                         {documents.map((doc: any) => (
                           <Link href={`/vault/${doc.id}`} key={doc.id}>
                             <div className="flex items-center gap-4 p-4 rounded-2xl bg-background shadow-sm border border-border/50 hover:shadow-md hover:border-primary/20 transition-all duration-300 cursor-pointer group">
                                <div className="h-10 w-10 rounded-xl bg-secondary flex items-center justify-center shrink-0">
                                  <FileText className="h-5 w-5 text-primary" />
                                </div>
                                <div className="flex-1 min-w-0">
                                  <p className="text-sm font-medium truncate">{doc.title}</p>
                                  <p className="text-xs text-muted-foreground">{doc.category}</p>
                                </div>
                             </div>
                           </Link>
                         ))}
                      </div>
                    ) : (
                      <>
                        <div className="h-14 w-14 rounded-full bg-secondary flex items-center justify-center mb-4">
                          <FileStack className="h-6 w-6 text-muted-foreground/60" />
                        </div>
                        <p className="font-medium text-sm mb-1">No documents attached yet.</p>
                        <p className="text-xs text-muted-foreground max-w-sm">Attach warranties, invoices, and manuals from the Vault to keep everything related to this object in one place.</p>
                      </>
                    )}
                  </div>
                </section>

                {/* Care & Maintenance Connection */}
                <div className="pt-10">
                   <div className="flex items-center justify-between mb-6">
                    <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Care & Maintenance</h3>
                    <Link href="/care/create">
                      <Button variant="ghost" size="sm" className="h-8 text-xs font-medium text-primary">Log Service</Button>
                    </Link>
                   </div>
                   <div className="bg-transparent border border-dashed border-border/60 rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                      {maintenance.length > 0 ? (
                        <div className="text-left w-full space-y-3">
                           {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                           {maintenance.map((m: any) => {
                             const isCompleted = m.status === "COMPLETED";
                             const isOverdue = m.status === "SCHEDULED" && new Date(m.scheduledDate) < new Date();
                             return (
                               <Link href={`/care/${m.id}`} key={m.id}>
                                 <div className="flex items-center gap-4 p-4 rounded-2xl bg-background shadow-sm border border-border/50 hover:shadow-md hover:border-primary/20 transition-all duration-300 cursor-pointer group">
                                    <div className={cn("h-10 w-10 rounded-xl flex items-center justify-center shrink-0 border transition-transform group-hover:scale-105", 
                                       isCompleted ? "bg-forest/10 text-forest border-forest/20" : 
                                       isOverdue ? "bg-terracotta/10 text-terracotta border-terracotta/20" : 
                                       "bg-primary/10 text-primary border-primary/20"
                                    )}>
                                      <Wrench className="h-5 w-5" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                      <p className="text-sm font-medium truncate group-hover:text-primary transition-colors">{m.title}</p>
                                      <p className={cn("text-xs", isOverdue ? "text-terracotta" : "text-muted-foreground")}>
                                        {isCompleted ? `Completed ${new Date(m.completedDate).toLocaleDateString()}` : `Due ${new Date(m.scheduledDate).toLocaleDateString()}`}
                                      </p>
                                    </div>
                                 </div>
                               </Link>
                             );
                           })}
                        </div>
                      ) : (
                        <>
                          <Wrench className="w-8 h-8 text-muted-foreground/30 mb-3" />
                          <p className="text-sm font-medium text-foreground">No maintenance records</p>
                          <p className="text-xs text-muted-foreground max-w-[200px] mt-1 mb-4">Protect the lifespan of this asset by logging service history.</p>
                          <Link href="/care/create">
                            <Button size="sm" variant="outline" className="h-8 text-xs rounded-lg">Add Record</Button>
                          </Link>
                        </>
                      )}
                   </div>
                </div>

                {/* Investment History */}
                <div className="pt-10">
                   <div className="flex items-center justify-between mb-6">
                    <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Investment History</h3>
                    <Link href="/money/create">
                      <Button variant="ghost" size="sm" className="h-8 text-xs font-medium text-primary">Log Expense</Button>
                    </Link>
                   </div>
                   <div className="bg-transparent border border-dashed border-border/60 rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                      {expenses.length > 0 ? (
                        <div className="text-left w-full space-y-3">
                           {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                           {expenses.map((exp: any) => (
                             <Link href={`/money/${exp.id}`} key={exp.id}>
                               <div className="flex items-center justify-between p-4 rounded-2xl bg-background shadow-sm border border-border/50 hover:shadow-md hover:border-primary/20 transition-all duration-300 cursor-pointer group">
                                  <div className="flex-1 min-w-0">
                                    <p className="text-sm font-medium truncate group-hover:text-primary transition-colors">{exp.title}</p>
                                    <p className="text-xs text-muted-foreground">{new Date(exp.expenseDate).toLocaleDateString()} • {exp.category}</p>
                                  </div>
                                  <p className="font-serif font-medium text-primary">${exp.amount.toLocaleString()}</p>
                               </div>
                             </Link>
                           ))}
                        </div>
                      ) : (
                        <>
                          <Banknote className="w-8 h-8 text-muted-foreground/30 mb-3" />
                          <p className="text-sm font-medium text-foreground">No expenses recorded</p>
                          <p className="text-xs text-muted-foreground max-w-[200px] mt-1 mb-4">Log maintenance costs or repairs to track the true cost of ownership.</p>
                          <Link href="/money/create">
                            <Button size="sm" variant="outline" className="h-8 text-xs rounded-lg">Add Record</Button>
                          </Link>
                        </>
                      )}
                   </div>
                </div>


              </motion.div>
            )}

            {activeTab === "timeline" && (
              <motion.div
                key="timeline"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
              >
                <div className="p-8 rounded-3xl bg-card border border-border/50 shadow-sm">
                  {activities && activities.length > 0 ? (
                    <Timeline>
                      {activities.map((act, i) => (
                        <TimelineItem 
                          key={act.id}
                          icon={Activity}
                          title={act.type.replace(/_/g, ' ')}
                          description={act.description}
                          time={new Date(act.createdAt).toLocaleDateString()}
                          isLast={i === activities.length - 1}
                        />
                      ))}
                    </Timeline>
                  ) : (
                    <div className="text-center py-12 text-muted-foreground">
                      <Activity className="h-8 w-8 mx-auto mb-3 opacity-20" />
                      <p className="text-sm font-medium">No activity recorded yet.</p>
                    </div>
                  )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Right Column - Sidecars */}
        <div className="lg:col-span-4 space-y-6">

          {/* Asset Health Engine */}
          <div className="p-6 rounded-3xl bg-card border border-border/50 shadow-sm">
             <div className="flex items-center gap-2 mb-4 text-primary">
               <Info className="h-4 w-4" />
               <h3 className="text-sm font-bold tracking-widest uppercase">Asset Health</h3>
             </div>

             <div className="flex items-end gap-2 mb-2">
                <span className="text-4xl font-serif leading-none text-primary">{healthScore}%</span>
                <span className="text-xs text-muted-foreground mb-1 font-medium">{healthScore === 100 ? "Complete" : "Incomplete"}</span>
             </div>

             <div className="h-2 w-full bg-secondary rounded-full overflow-hidden mb-4">
                <motion.div 
                  initial={{ width: 0 }}
                  animate={{ width: `${healthScore}%` }}
                  transition={{ duration: 1, ease: "easeOut" }}
                  className="h-full bg-primary rounded-full"
                />
             </div>

             {isLearning && (
               <p className="text-xs text-muted-foreground leading-relaxed">
                 Your asset profile is still learning. Add missing information like purchase details and brand identity to reach 100%.
               </p>
             )}
          </div>

          {/* Visual Relationships */}
          <div className="p-6 rounded-3xl bg-card border border-border/50 shadow-sm">
             <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-6">Connections</h3>

             <div className="flex flex-col gap-4 relative">
               <div className="absolute left-6 top-6 bottom-6 w-0.5 bg-border/50 z-0" />

               <div className="flex items-center gap-4 relative z-10 group">
                 <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center shrink-0 text-primary">
                   <Wrench className="h-5 w-5" />
                 </div>
                 <div className="flex-1">
                   <p className="text-[10px] font-bold tracking-widest uppercase text-primary">Service Health</p>
                   {upcomingService ? (
                     <p className="text-sm font-medium truncate">Due {new Date(upcomingService.scheduledDate).toLocaleDateString()}</p>
                   ) : lastMaintenance ? (
                     <p className="text-sm font-medium truncate">Last serviced {new Date(lastMaintenance.completedDate).toLocaleDateString()}</p>
                   ) : (
                     <p className="text-sm font-medium truncate">No service records</p>
                   )}
                 </div>
               </div>

               <div className="flex items-center gap-4 relative z-10 group">
                 <div className="h-12 w-12 rounded-full bg-secondary flex items-center justify-center border-2 border-background shadow-sm transition-transform group-hover:scale-110">
                   <Tag className="h-5 w-5 text-muted-foreground" />
                 </div>
                 <div className="flex-1">
                   <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground">Space</p>
                   <p className="text-sm font-medium truncate">{asset.space?.name || "Unassigned"}</p>
                 </div>
               </div>

               <div className="flex items-center gap-4 relative z-10 group">
                 <div className="h-12 w-12 rounded-full bg-secondary flex items-center justify-center border-2 border-background shadow-sm transition-transform group-hover:scale-110">
                   <FileText className="h-5 w-5 text-muted-foreground" />
                 </div>
                 <div className="flex-1">
                   <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground">Documents</p>
                   <p className="text-sm font-medium truncate">{documents.length} attached</p>
                 </div>
               </div>
             </div>
          </div>

          {/* QR Identity */}
          <div className="p-6 rounded-3xl bg-card border border-border/50 shadow-sm flex flex-col items-center text-center">
            <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-4 w-full text-left">Digital Identity</h3>
            <div className="p-4 bg-white rounded-2xl shadow-sm border border-border/40 inline-block mb-4 hover:scale-105 transition-transform duration-500">
              <QRCodeSVG value={qrUrl} size={140} level="M" />
            </div>
            <p className="text-xs text-muted-foreground px-2 mb-4">
              Unique digital tag. Print and attach to your physical object for quick scanning.
            </p>
            <div className="flex gap-2 w-full">
              <Button variant="outline" className="flex-1 rounded-xl text-xs"><Share2 className="h-3 w-3 mr-2" /> Share</Button>
              <Button variant="secondary" className="flex-1 rounded-xl text-xs">Print Tag</Button>
            </div>
          </div>

          {relationshipsPanel}

        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { PageHeader } from "@/components/layout/page-header";
import { motion } from "framer-motion";
import { useHome } from "@/components/providers/home-provider";
import { useOnboarding } from "@/hooks/use-onboarding";
import { ModuleSkeleton } from "@/components/ui/module-skeleton";
import { EmptyState } from "@/components/ui/empty-state";
import { EmptyAssetsIllustration } from "@/components/ui/illustrations";
import { PackageOpen, Search, Plus, Filter } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { AssetCard } from "./components/asset-card";
import { Button } from "@/components/ui/button";

export default function AssetsPage() {
  const router = useRouter();
  const { activeHome } = useHome();
  const { completion } = useOnboarding();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const { data: assets, isLoading } = useQuery({
    queryKey: ["assets", activeHome?.id, searchQuery, activeCategory],
    queryFn: async () => {
      if (!activeHome?.id) return [];
      const params = new URLSearchParams();
      if (searchQuery) params.append("q", searchQuery);
      if (activeCategory) params.append("category", activeCategory);

      const res = await fetch(`/api/assets?${params.toString()}`, {
        headers: { "x-home-id": activeHome.id }
      });
      if (!res.ok) throw new Error("Failed to fetch assets");
      return res.json();
    },
    enabled: !!activeHome?.id,
  });

  if (!activeHome || isLoading) {
    return <ModuleSkeleton type="bento" />;
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const categories = Array.from(new Set(assets?.map((a: any) => a.category) || []));

  return (
    <div className="max-w-[1400px] mx-auto px-6 lg:px-12 pt-12 pb-32 space-y-10">
      <PageHeader
        title="My Assets"
        description="Everything your home owns, organized beautifully."
        actions={
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            <Link href="/assets/create" className="inline-flex items-center justify-center h-12 px-6 rounded-full font-medium bg-primary text-primary-foreground hover:scale-[0.98] transition-transform shadow-float">
              <Plus className="h-5 w-5 mr-2" />
              Add Asset
            </Link>
          </motion.div>
        }
      />

      {assets?.length === 0 && !searchQuery && !activeCategory ? (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
        >
          <EmptyState
            illustration={<EmptyAssetsIllustration />}
            title={!completion.isComplete ? "Your home has rooms." : "Your home has no objects yet."}
            description={!completion.isComplete ? "Now let's help it remember what lives inside them." : "Add appliances, furniture and important belongings to create their digital identity."}
            actionLabel="Add Asset"
            onAction={() => router.push("/assets/create")}
          />
        </motion.div>
      ) : (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="space-y-8"
        >
          {/* Controls */}
          <div className="flex flex-col sm:flex-row gap-4 items-center justify-between bg-card/50 backdrop-blur-md border border-border/50 p-4 rounded-3xl">
            <div className="relative w-full sm:w-96">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground/60" />
              <input
                type="text"
                placeholder="Search assets..."
                className="w-full h-12 pl-12 pr-4 bg-background border border-border/60 rounded-2xl text-sm focus-visible:outline-none focus-visible:border-primary/50 focus-visible:ring-2 focus-visible:ring-primary/20 hover:border-border transition-colors placeholder:text-muted-foreground"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 scrollbar-none">
              <Button
                variant={activeCategory === null ? "default" : "outline"}
                size="sm"
                onClick={() => setActiveCategory(null)}
                className="rounded-full h-10 px-5 font-medium shrink-0"
              >
                All
              </Button>
              {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
              {categories.map((category: any) => (
                <Button
                  key={category}
                  variant={activeCategory === category ? "default" : "outline"}
                  size="sm"
                  onClick={() => setActiveCategory(category)}
                  className="rounded-full h-10 px-5 font-medium shrink-0"
                >
                  {category}
                </Button>
              ))}
              <Button aria-label="Filter options" variant="ghost" size="icon" className="h-10 w-10 rounded-full shrink-0 border border-border/40 bg-background/50">
                <Filter className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* Grid */}
          {assets?.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 sm:gap-6">
              {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
              {assets.map((asset: any) => (
                <AssetCard key={asset.id} asset={asset} />
              ))}
            </div>
          ) : (
            <div className="py-24 text-center">
              <p className="text-lg font-serif text-muted-foreground">No assets found matching your criteria.</p>
              <Button variant="link" onClick={() => { setSearchQuery(""); setActiveCategory(null); }} className="mt-2 text-primary">
                Clear filters
              </Button>
            </div>
          )}
        </motion.div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { ArrowLeft, CheckCircle2, Calendar, MapPin, PackageOpen, AlertTriangle, FileText, Banknote, History, Wrench } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Timeline, TimelineItem } from "@/components/ui/timeline";
import { cn } from "@/lib/utils";
import { useRouter } from "next/navigation";
import { DocumentCard } from "@/app/(app)/vault/components/document-card";
import { ConnectedHomeGraph, GraphNode } from "@/components/graph/connected-home-graph";
import { useRecentStore } from "@/store/recent-store";
import { useEffect } from "react";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function MaintenanceDetailClient({ maintenance, activities, relationshipsPanel }: { maintenance: any; activities: any[]; relationshipsPanel?: React.ReactNode }) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const addRecent = useRecentStore((state) => state.addRecent);

  useEffect(() => {
    addRecent({
      id: maintenance.id,
      title: maintenance.title,
      type: "maintenance",
      url: `/care/${maintenance.id}`
    });
  }, [maintenance.id, maintenance.title, addRecent]);

  const isCompleted = maintenance.status === "COMPLETED";
  const isOverdue = maintenance.status === "SCHEDULED" && new Date(maintenance.scheduledDate) < new Date();

  const handleMarkComplete = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/care/${maintenance.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "COMPLETED" }),
      });
      if (res.ok) {
        router.refresh();
      }
    } finally {
      setLoading(false);
    }
  };

  // Connected Home Graph Data
  const centralNode: GraphNode = {
    id: maintenance.id,
    type: "MAINTENANCE",
    name: maintenance.title,
    subtitle: maintenance.category,
    link: `/care/${maintenance.id}`
  };

  const satellites: GraphNode[] = [];
  if (maintenance.space) {
    satellites.push({
      id: maintenance.space.id,
      type: "SPACE",
      name: maintenance.space.name,
      subtitle: "Related Space",
      link: `/spaces/${maintenance.space.id}`
    });
  }
  if (maintenance.asset) {
    satellites.push({
      id: maintenance.asset.id,
      type: "ASSET",
      name: maintenance.asset.name,
      subtitle: "Related Asset",
      link: `/assets/${maintenance.asset.id}`
    });
  }
  if (maintenance.createdBy) {
    satellites.push({
      id: maintenance.createdBy.id,
      type: "MEMBER",
      name: maintenance.createdBy.name || "Unknown",
      subtitle: "Created By",
      link: `/family/${maintenance.createdBy.id}`
    });
  }
  if (maintenance.assignedTo && maintenance.assignedTo.id !== maintenance.createdBy?.id) {
    satellites.push({
      id: maintenance.assignedTo.id,
      type: "MEMBER",
      name: maintenance.assignedTo.name || "Unknown",
      subtitle: "Assigned To",
      link: `/family/${maintenance.assignedTo.id}`
    });
  }
  if (maintenance.documents) {
    maintenance.documents.forEach((doc: any) => satellites.push({
      id: doc.id,
      type: "DOCUMENT",
      name: doc.title,
      link: `/vault/${doc.id}`
    }));
  }
  if (maintenance.expenses) {
    maintenance.expenses.forEach((e: any) => satellites.push({
      id: e.id,
      type: "EXPENSE",
      name: e.title,
      subtitle: `${e.currency || '₹'} ${e.amount}`,
      link: `/money/${e.id}`
    }));
  }

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-10 pb-24">
      {/* Navigation */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/care" className="p-2 rounded-full hover:bg-secondary/60 transition-colors">
            <ArrowLeft className="h-5 w-5 text-muted-foreground" />
          </Link>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Link href="/care" className="hover:text-foreground transition-colors">Care</Link>
            <span>/</span>
            <span className="text-foreground font-medium truncate max-w-[200px]">{maintenance.title}</span>
          </div>
        </div>
        <Link href={`/home/timeline?targetId=${maintenance.id}&targetType=MAINTENANCE`}>
          <Button variant="outline" size="sm" className="rounded-full shadow-sm text-muted-foreground hover:text-foreground font-bold tracking-widest uppercase text-[10px]">
            History
          </Button>
        </Link>
      </div>

      {/* Connected Home Section */}
      <section className="space-y-6 pt-6">
        <h2 className="text-xl font-serif tracking-tight text-primary">Connected Home</h2>
        <ConnectedHomeGraph centralNode={centralNode} satellites={satellites} />
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Left Column: Details & Attachments */}
        <div className="lg:col-span-8 space-y-10">

          <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm space-y-8 relative overflow-hidden">

             {/* Header */}
             <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 relative z-10">
               <div className="space-y-4">
                 <div className="flex items-center gap-2">
                   <span className="text-[10px] font-bold tracking-widest uppercase px-3 py-1 rounded-full bg-secondary text-muted-foreground border border-border/50">
                     {maintenance.category}
                   </span>
                   {maintenance.priority === "CRITICAL" || maintenance.priority === "HIGH" ? (
                     <span className="text-[10px] font-bold tracking-widest uppercase text-terracotta flex items-center gap-1">
                       <AlertTriangle className="h-3.5 w-3.5" /> {maintenance.priority}
                     </span>
                   ) : null}
                 </div>
                 <h1 className="text-3xl md:text-4xl font-serif text-primary">{maintenance.title}</h1>
                 {maintenance.description && (
                   <p className="text-muted-foreground max-w-xl">{maintenance.description}</p>
                 )}
               </div>

               {/* Large Status Indicator */}
               <div className={cn(
                 "shrink-0 w-32 h-32 rounded-full border-4 flex flex-col items-center justify-center rotate-[-5deg]",
                 isCompleted ? "border-forest/20 text-forest bg-forest/5" :
                 isOverdue ? "border-terracotta/20 text-terracotta bg-terracotta/5" :
                 "border-primary/20 text-primary bg-primary/5"
               )}>
                 {isCompleted ? <CheckCircle2 className="h-10 w-10 mb-1" /> :
                  isOverdue ? <AlertTriangle className="h-10 w-10 mb-1" /> :
                  <Calendar className="h-10 w-10 mb-1" />}
                 <span className="text-[10px] font-bold tracking-widest uppercase">
                   {isCompleted ? "Done" : isOverdue ? "Overdue" : "Scheduled"}
                 </span>
               </div>
             </div>

             {/* Meta Grid */}
             <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-6 border-t border-border/40 relative z-10">
                <div>
                  <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Target</p>
                  {maintenance.asset ? (
                    <div className="flex items-center gap-1.5 text-sm font-medium">
                      <PackageOpen className="h-4 w-4 text-muted-foreground" /> <Link href={`/assets/${maintenance.asset.id}`} className="hover:text-primary transition-colors">{maintenance.asset.name}</Link>
                    </div>
                  ) : maintenance.space ? (
                    <div className="flex items-center gap-1.5 text-sm font-medium">
                      <MapPin className="h-4 w-4 text-muted-foreground" /> <Link href={`/spaces/${maintenance.space.id}`} className="hover:text-primary transition-colors">{maintenance.space.name}</Link>
                    </div>
                  ) : (
                    <div className="flex items-center gap-1.5 text-sm font-medium">
                      <Wrench className="h-4 w-4 text-muted-foreground" /> Home
                    </div>
                  )}
                </div>

                <div>
                  <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Due Date</p>
                  <p className="text-sm font-medium">{new Date(maintenance.scheduledDate).toLocaleDateString()}</p>
                </div>

                <div>
                  <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Frequency</p>
                  <p className="text-sm font-medium capitalize">{maintenance.frequency.toLowerCase()}</p>
                </div>

                <div>
                  <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Cost</p>
                  <p className="text-sm font-medium">
                    {maintenance.actualCost ? `$${maintenance.actualCost}` : maintenance.estimatedCost ? `Est. $${maintenance.estimatedCost}` : "TBD"}
                  </p>
                </div>
             </div>
          </div>

          <section className="space-y-6">
             <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm">
               <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-6">Responsibilities</h2>
               <div className="grid grid-cols-2 gap-6">
                 <div>
                   <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-2">Assigned To</p>
                   { }
                   {maintenance.assignedTo ? (
                     <div className="flex items-center gap-2">
                       <div className="h-6 w-6 rounded-full bg-secondary overflow-hidden shrink-0">
                         {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                         {(maintenance.assignedTo as any).avatar ? <img src={(maintenance.assignedTo as any).avatar} alt="" /> : <div className="w-full h-full flex items-center justify-center text-xs font-bold">{(maintenance.assignedTo as any).name?.charAt(0)}</div>}
                       </div>
                       {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                       <span className="text-sm font-medium">{(maintenance.assignedTo as any).name}</span>
                     </div>
                   ) : (
                     <span className="text-sm text-muted-foreground">Unassigned</span>
                   )}
                 </div>

                 <div>
                   <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-2">Completed By</p>
                   { }
                   {maintenance.completedBy ? (
                     <div className="flex items-center gap-2">
                       <div className="h-6 w-6 rounded-full bg-secondary overflow-hidden shrink-0">
                         {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                         {(maintenance.completedBy as any).avatar ? <img src={(maintenance.completedBy as any).avatar} alt="" /> : <div className="w-full h-full flex items-center justify-center text-xs font-bold">{(maintenance.completedBy as any).name?.charAt(0)}</div>}
                       </div>
                       {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                       <span className="text-sm font-medium">{(maintenance.completedBy as any).name}</span>
                     </div>
                   ) : (
                     <span className="text-sm text-muted-foreground">—</span>
                   )}
                 </div>
               </div>
             </div>
          </section>

          <section className="space-y-6">
             <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm space-y-6">
               <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Financials</h2>
               {maintenance.expenses && maintenance.expenses.length > 0 ? (
                 <div className="space-y-4">
                   <div className="flex items-center justify-between pb-4 border-b border-border/50">
                      <p className="text-sm font-medium text-muted-foreground">Total Logged Cost</p>
                      {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                      <p className="text-xl font-serif">${maintenance.expenses.reduce((sum: number, e: any) => sum + e.amount, 0).toLocaleString()}</p>
                   </div>
                   <div className="space-y-3">
                     {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                     {maintenance.expenses.map((exp: any) => (
                       <Link href={`/money/${exp.id}`} key={exp.id}>
                         <div className="flex items-center justify-between p-4 rounded-2xl bg-background shadow-sm border border-border/50 hover:shadow-md hover:border-primary/20 transition-all duration-300 cursor-pointer group">
                            <div>
                              <p className="text-sm font-medium">{exp.title}</p>
                              <p className="text-xs text-muted-foreground">{new Date(exp.expenseDate).toLocaleDateString()}</p>
                            </div>
                            <p className="font-serif font-medium text-primary">${exp.amount.toLocaleString()}</p>
                         </div>
                       </Link>
                     ))}
                   </div>
                 </div>
               ) : (
                 <div className="bg-transparent border border-dashed border-border/60 rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                   <p className="text-sm font-medium text-muted-foreground mb-1">No recorded expenses</p>
                   <Link href={`/money/create?maintenanceId=${maintenance.id}`}>
                     <Button variant="link" className="text-xs h-auto p-0">Log an expense</Button>
                   </Link>
                 </div>
               )}
             </div>
          </section>

          {/* Attachments from Vault */}
          <section className="space-y-6">
             <div className="flex items-center justify-between">
               <div className="flex items-center gap-2">
                 <FileText className="h-5 w-5 text-muted-foreground" />
                 <h3 className="text-sm font-bold tracking-widest uppercase">Vault Attachments</h3>
               </div>
               <Button variant="outline" size="sm" className="hidden sm:flex text-xs rounded-xl shadow-sm"><FileText className="h-3.5 w-3.5 mr-2" /> Connect Document</Button>
             </div>

             {maintenance.documents && maintenance.documents.length > 0 ? (
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                 {maintenance.documents.map((doc: any) => (
                   <DocumentCard key={doc.id} document={doc} />
                 ))}
               </div>
             ) : (
               <div className="bg-transparent border border-dashed border-border/60 rounded-3xl p-8 flex flex-col items-center justify-center text-center text-muted-foreground space-y-3">
                 <FileText className="h-8 w-8 opacity-40" />
                 <p className="text-sm">No documents attached.</p>
                 <Button variant="outline" size="sm" className="mt-2 text-xs">Upload Invoice / Report</Button>
               </div>
             )}
          </section>

        </div>

        {/* Right Column: Actions & History */}
        <div className="lg:col-span-4 space-y-8">

           {/* Actions Card */}
           <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm space-y-6 text-center">
              {isCompleted ? (
                <div className="space-y-3">
                  <div className="h-16 w-16 bg-forest/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-forest/20">
                    <CheckCircle2 className="h-8 w-8 text-forest" />
                  </div>
                  <h3 className="font-serif text-xl text-foreground">Maintenance Complete</h3>
                  <p className="text-sm text-muted-foreground">
                    Completed by {maintenance.completedBy?.name || "System"} on {new Date(maintenance.completedDate).toLocaleDateString()}.
                  </p>
                  {maintenance.frequency !== "ONCE" && (
                    <div className="mt-4 p-3 bg-secondary rounded-xl text-xs flex items-center justify-center gap-2 text-muted-foreground">
                      <Calendar className="h-3.5 w-3.5" /> Next occurrence has been automatically scheduled.
                    </div>
                  )}
                </div>
              ) : (
                <div className="space-y-4">
                  <h3 className="font-serif text-xl text-foreground">Action Required</h3>
                  <Button 
                    onClick={handleMarkComplete}
                    disabled={loading}
                    className="w-full h-14 rounded-2xl shadow-float bg-forest hover:bg-forest/90 text-white font-medium"
                  >
                    {loading ? "Updating..." : "Mark as Completed"} <CheckCircle2 className="h-5 w-5 ml-2" />
                  </Button>
                  <Link href={`/money/create?maintenanceId=${maintenance.id}`}>
                    <Button variant="outline" className="w-full h-14 rounded-2xl shadow-sm font-medium">
                      Log Expenses <Banknote className="h-5 w-5 ml-2 text-muted-foreground" />
                    </Button>
                  </Link>
                </div>
              )}
           </div>

           {/* Timeline */}
           <div className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm">
             <div className="flex items-center gap-2 mb-8">
               <History className="h-5 w-5 text-muted-foreground" />
               <h3 className="text-sm font-bold tracking-widest uppercase">History</h3>
             </div>

             {activities && activities.length > 0 ? (
                <Timeline>
                  {activities.map((act, i) => (
                    <TimelineItem 
                      key={act.id}
                      icon={Wrench}
                      title={act.type.replace(/_/g, ' ')}
                      description={act.description}
                      time={new Date(act.createdAt).toLocaleDateString()}
                      isLast={i === activities.length - 1}
                    />
                  ))}
                </Timeline>
              ) : (
                <p className="text-sm text-muted-foreground">No history available.</p>
              )}
           </div>

           {relationshipsPanel}

        </div>

      </div>
    </div>
  );
}

import { prisma } from "@/lib/prisma";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { ModuleSkeleton } from "@/components/ui/module-skeleton";
import { EmptyState } from "@/components/ui/empty-state";
import { EmptyCareIllustration } from "@/components/ui/illustrations";
import { CareDashboardClient } from "./components/care-dashboard-client";

export const dynamic = "force-dynamic";

export default async function CarePage() {
  const cookieStore = await cookies();
  const homeId = cookieStore.get("homeId")?.value;

  if (!homeId) {
    redirect("/select-home");
  }

  // Efficient aggregate queries
  const allMaintenance = await prisma.maintenance.findMany({
    where: { homeId },
    include: {
      space: { select: { id: true, name: true } },
      asset: { select: { id: true, name: true } },
    },
    orderBy: { scheduledDate: "asc" }
  });

  const assetsCount = await prisma.asset.count({ where: { homeId } });

  if (allMaintenance.length === 0) {
    return (
      <div className="pt-24">
        <EmptyState
          illustration={<EmptyCareIllustration />}
          title="Your home is running smoothly."
          description="Keep it that way by scheduling routine maintenance like changing AC filters or inspecting the roof."
          actionLabel="Schedule Task"
          actionHref="/care/create"
        />
      </div>
    );
  }

  return (
    <CareDashboardClient 
      initialMaintenance={allMaintenance} 
      totalAssets={assetsCount} 
    />
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { useHome } from "@/components/providers/home-provider";
import { ArrowLeft, Box, CheckCircle2, Clock, FileText, LayoutDashboard, Receipt, ShieldCheck } from "lucide-react";
import Link from "next/link";
import { Timeline, TimelineItem } from "@/components/ui/timeline";
import { Button } from "@/components/ui/button";
import { ConnectedHomeGraph, GraphNode } from "@/components/graph/connected-home-graph";
import { useRecentStore } from "@/store/recent-store";
import { useEffect } from "react";

export function MemberProfileClient({ memberId, relationshipsPanel }: { memberId: string; relationshipsPanel?: React.ReactNode }) {
  const { activeHome } = useHome();
  const addRecent = useRecentStore((state) => state.addRecent);

  const { data: member, isLoading } = useQuery({
    queryKey: ["family", activeHome?.id, memberId],
    queryFn: async () => {
      const res = await fetch(`/api/family/${memberId}`, { headers: { "x-home-id": activeHome!.id } });
      if (!res.ok) throw new Error("Failed to fetch member");
      return res.json();
    },
    enabled: !!activeHome?.id,
  });

  useEffect(() => {
    if (member) {
      addRecent({
        id: member.id,
        title: member.name || "Unknown Member",
        type: "member",
        url: `/family/${member.id}`
      });
    }
  }, [member, addRecent]);

  if (isLoading || !member) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-pulse space-y-12">
        <div className="flex items-center gap-6"><div className="h-24 w-24 rounded-full bg-secondary" /><div className="space-y-3"><div className="h-6 w-48 bg-secondary rounded" /><div className="h-4 w-32 bg-secondary rounded" /></div></div>
        <div className="h-64 bg-secondary rounded-3xl" />
      </div>
    );
  }

  const { contributions, responsibilities, activity } = member;
  const totalContributions = 
    contributions.assets.length + 
    contributions.spaces.length + 
    contributions.documents.length + 
    contributions.maintenance.length + 
    contributions.expenses.length;

  // Connected Home Graph Data
  const centralNode: GraphNode = {
    id: member.id,
    type: "MEMBER",
    name: member.name || "Unknown",
    subtitle: member.role,
    link: `/family/${member.id}`
  };

  const satellites: GraphNode[] = [];

  const maxSatellites = 15;
  let count = 0;

  for (const asset of member.contributions.assets) {
    if (count++ >= maxSatellites) break;
    satellites.push({
      id: asset.id,
      type: "ASSET",
      name: asset.name,
      link: `/assets/${asset.id}`
    });
  }
  for (const space of member.contributions.spaces) {
    if (count++ >= maxSatellites) break;
    satellites.push({
      id: space.id,
      type: "SPACE",
      name: space.name,
      link: `/spaces/${space.id}`
    });
  }
  for (const doc of member.contributions.documents) {
    if (count++ >= maxSatellites) break;
    satellites.push({
      id: doc.id,
      type: "DOCUMENT",
      name: doc.title,
      link: `/vault/${doc.id}`
    });
  }
  for (const m of member.contributions.maintenance) {
    if (count++ >= maxSatellites) break;
    satellites.push({
      id: m.id,
      type: "MAINTENANCE",
      name: m.title,
      link: `/care/${m.id}`
    });
  }
  for (const e of member.contributions.expenses) {
    if (count++ >= maxSatellites) break;
    satellites.push({
      id: e.id,
      type: "EXPENSE",
      name: e.title,
      subtitle: `₹ ${e.amount}`,
      link: `/money/${e.id}`
    });
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-12 pb-32">

      <div className="flex items-center justify-between">
        <Link href="/family" className="inline-flex items-center text-sm font-medium text-muted-foreground hover:text-primary transition-colors">
          <ArrowLeft className="h-4 w-4 mr-1" /> Back to Family
        </Link>
        <Link href={`/home/timeline?targetId=${memberId}&targetType=MEMBER`}>
          <Button variant="outline" size="sm" className="rounded-full shadow-sm text-muted-foreground hover:text-foreground font-bold tracking-widest uppercase text-[10px]">
            History
          </Button>
        </Link>
      </div>

      <section className="flex flex-col sm:flex-row items-start sm:items-center gap-6 pb-8 border-b border-border/40">
        <div className="relative h-24 w-24 sm:h-32 sm:w-32 rounded-full overflow-hidden bg-secondary flex-shrink-0 border-4 border-background shadow-sm">
           {member.avatar ? (
                 /* eslint-disable-next-line @next/next/no-img-element */ <img src={member.avatar} alt={member.name} className="w-full h-full object-cover" />
           ) : (
             <div className="w-full h-full flex items-center justify-center text-3xl font-serif text-muted-foreground">
               {(member.name || member.email || "?").charAt(0).toUpperCase()}
             </div>
           )}
        </div>

        <div>
          <h1 className="text-4xl font-serif text-primary mb-2">{member.name || "Unnamed Member"}</h1>
          <div className="flex flex-wrap items-center gap-3 text-sm">
             <span className="px-2.5 py-0.5 rounded-full bg-primary/10 text-primary font-bold tracking-widest uppercase text-[10px]">
               {member.role}
             </span>
             <span className="text-muted-foreground">{member.email}</span>
             <span className="text-muted-foreground">• Joined {new Date(member.joinedAt).toLocaleDateString()}</span>
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
         <div className="md:col-span-1 space-y-8">
            <section className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm">
               <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-6">Contribution Summary</h3>
               <div className="space-y-5">
                 <div className="flex items-center justify-between">
                   <div className="flex items-center gap-3 text-sm text-muted-foreground"><Box className="h-4 w-4" /> Assets Added</div>
                   <span className="font-medium">{contributions.assets.length}</span>
                 </div>
                 <div className="flex items-center justify-between">
                   <div className="flex items-center gap-3 text-sm text-muted-foreground"><LayoutDashboard className="h-4 w-4" /> Spaces Created</div>
                   <span className="font-medium">{contributions.spaces.length}</span>
                 </div>
                 <div className="flex items-center justify-between">
                   <div className="flex items-center gap-3 text-sm text-muted-foreground"><FileText className="h-4 w-4" /> Documents Uploaded</div>
                   <span className="font-medium">{contributions.documents.length}</span>
                 </div>
                 <div className="flex items-center justify-between">
                   <div className="flex items-center gap-3 text-sm text-muted-foreground"><ShieldCheck className="h-4 w-4" /> Maintenance Done</div>
                   <span className="font-medium">{contributions.maintenance.length}</span>
                 </div>
                 <div className="flex items-center justify-between">
                   <div className="flex items-center gap-3 text-sm text-muted-foreground"><Receipt className="h-4 w-4" /> Expenses Logged</div>
                   <span className="font-medium">{contributions.expenses.length}</span>
                 </div>

                 <div className="pt-4 border-t border-border/40 flex justify-between items-center text-primary">
                    <span className="text-xs font-bold tracking-widest uppercase">Total Impact</span>
                    <span className="font-serif text-2xl">{totalContributions}</span>
                 </div>
               </div>
            </section>

            {responsibilities.length > 0 && (
              <section className="bg-primary/5 border border-primary/10 rounded-3xl p-6 md:p-8 shadow-sm">
                 <h3 className="text-sm font-bold tracking-widest uppercase text-primary mb-6">Active Responsibilities</h3>
                 <div className="space-y-4">
                   {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                   {responsibilities.map((resp: any) => (
                     <div key={resp.id} className="bg-background rounded-2xl p-4 shadow-sm">
                        <p className="font-medium text-sm mb-1">{resp.title}</p>
                        <p className="text-xs text-muted-foreground flex items-center gap-1"><Clock className="w-3 h-3"/> Due: {new Date(resp.scheduledDate).toLocaleDateString()}</p>
                     </div>
                   ))}
                 </div>
              </section>
            )}
         </div>

         <div className="md:col-span-2 space-y-8">
            <section className="space-y-6">
              <h2 className="text-xl font-serif tracking-tight text-primary">Connected Home</h2>
              <ConnectedHomeGraph centralNode={centralNode} satellites={satellites} />
            </section>

            <section className="bg-card border border-border/50 rounded-3xl p-6 md:p-8 shadow-sm">
               <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground mb-8">Recent Activity</h3>
               {activity.length > 0 ? (
                 <Timeline>
                   {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                   {activity.map((act: any, i: number) => (
                     <TimelineItem
                       key={act.id}
                       icon={CheckCircle2}
                       title={act.type.replace(/_/g, ' ')}
                       description={act.description}
                       time={new Date(act.createdAt).toLocaleDateString()}
                       isLast={i === activity.length - 1}
                     />
                   ))}
                 </Timeline>
               ) : (
                 <p className="text-muted-foreground">No recent activity.</p>
               )}
            </section>
         </div>
      </div>

    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

import { useHome } from "@/components/providers/home-provider";
import { useQuery } from "@tanstack/react-query";
import { Users, UserPlus, Shield, Check, Copy, Mail, Clock, Activity, X } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Timeline, TimelineItem } from "@/components/ui/timeline";
import { Card } from "@/components/ui/card";
import { useOnboarding } from "@/hooks/use-onboarding";
import { EmptyState } from "@/components/ui/empty-state";
import { PageHeader } from "@/components/layout/page-header";

export function FamilyDashboardClient() {
  const { activeHome } = useHome();
  const [inviteModalOpen, setInviteModalOpen] = useState(false);
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("MEMBER");
  const [inviting, setInviting] = useState(false);
  const [copiedCode, setCopiedCode] = useState<string | null>(null);
  const { completion } = useOnboarding();

  const { data, refetch, isLoading } = useQuery({
    queryKey: ["family", activeHome?.id],
    queryFn: async () => {
      if (!activeHome?.id) return null;
      const res = await fetch("/api/family", { headers: { "x-home-id": activeHome.id } });
      if (!res.ok) throw new Error("Failed to fetch family data");
      return res.json();
    },
    enabled: !!activeHome?.id,
  });

  const handleInvite = async (e: React.FormEvent) => {
    e.preventDefault();
    setInviting(true);
    try {
      await fetch("/api/homes/invitations", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-home-id": activeHome!.id },
        body: JSON.stringify({ role: inviteRole, email: inviteEmail })
      });
      setInviteEmail("");
      setInviteRole("MEMBER");
      setInviteModalOpen(false);
      refetch();
    } catch (err) {
      console.error(err);
    } finally {
      setInviting(false);
    }
  };

  const handleRevoke = async (id: string) => {
    if (!window.confirm("Revoke this invitation?")) return;
    try {
      await fetch(`/api/homes/invitations?id=${id}`, {
        method: "DELETE",
        headers: { "x-home-id": activeHome!.id }
      });
      refetch();
    } catch (err) {
      console.error(err);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedCode(text);
    setTimeout(() => setCopiedCode(null), 2000);
  };

  if (isLoading || !data) {
    return (
      <div className="max-w-[1400px] mx-auto px-6 lg:px-12 pt-12 pb-32 space-y-10 animate-pulse">
         <div className="h-10 bg-secondary/50 rounded-xl w-48 mb-8" />
         <div className="grid grid-cols-2 md:grid-cols-4 gap-4"><div className="h-24 bg-secondary/50 rounded-2xl" /><div className="h-24 bg-secondary/50 rounded-2xl" /></div>
      </div>
    );
  }

  const { overview, members, invitations, recentActivity } = data;

  return (
    <div className="max-w-[1400px] mx-auto px-6 lg:px-12 pt-12 pb-32 space-y-10">

      <PageHeader
        title="The People"
        description="Collaborate, assign responsibilities, and manage access."
        actions={
          <Button onClick={() => setInviteModalOpen(true)} className="rounded-2xl h-12 px-6 shadow-float bg-primary text-primary-foreground shrink-0">
             <UserPlus className="h-5 w-5 mr-2" /> Invite Member
          </Button>
        }
      />

      {/* Household Overview */}
      <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
         <div className="p-6 bg-card border border-border/50 rounded-3xl shadow-sm flex flex-col justify-center">
           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Total Members</p>
           <p className="text-3xl font-serif">{overview.totalMembers}</p>
         </div>
         <div className="p-6 bg-card border border-border/50 rounded-3xl shadow-sm flex flex-col justify-center">
           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Total Contributions</p>
           {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
           <p className="text-3xl font-serif">{members.reduce((sum: number, m: any) => sum + m.stats.contributions, 0)}</p>
         </div>
         <div className="p-6 bg-card border border-border/50 rounded-3xl shadow-sm flex flex-col justify-center">
           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Avg Participation</p>
           <p className="text-3xl font-serif">{overview.averageParticipation} <span className="text-sm text-muted-foreground font-sans font-medium">acts/member</span></p>
         </div>
         <div className="p-6 bg-card border border-border/50 rounded-3xl shadow-sm flex flex-col justify-center">
           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground mb-1">Pending Invites</p>
           {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
           <p className="text-3xl font-serif">{invitations.filter((i: any) => i.status === "PENDING").length}</p>
         </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Members & Invitations */}
        <div className="lg:col-span-2 space-y-12">

          <section className="space-y-6">
            <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground flex items-center gap-2"><Users className="h-4 w-4" /> Household Members</h2>

            {members.length === 1 && !completion.isComplete ? (
              <Card className="p-8 md:p-16 border border-border/50 bg-card shadow-sm rounded-[2.5rem]">
                <EmptyState
                  icon={Users}
                  title="A home becomes smarter when everyone contributes."
                  description="Invite family members, roommates, or property managers to collaborate on managing your household."
                  actionLabel="Invite Family"
                  onAction={() => setInviteModalOpen(true)}
                />
              </Card>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
              {members.map((member: any) => (
                <Link href={`/family/${member.id}`} key={member.id}>
                  <motion.div 
                    whileHover={{ y: -4, scale: 1.01 }}
                    className="group relative p-6 bg-card border border-border/50 rounded-3xl shadow-sm hover:shadow-md hover:border-primary/30 transition-all cursor-pointer overflow-hidden"
                  >
                    <div className="absolute inset-0 bg-gradient-to-br from-primary/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                    <div className="relative z-10">
                      <div className="flex items-start justify-between mb-4">
                         <div className="h-12 w-12 rounded-full bg-secondary overflow-hidden shrink-0">
                           {member.avatar ? (
                                 /* eslint-disable-next-line @next/next/no-img-element */ <img src={member.avatar} alt={member.name || "Member"} className="w-full h-full object-cover" />
                           ) : (
                             <div className="w-full h-full flex items-center justify-center text-muted-foreground text-lg font-serif">
                               {(member.name || member.email || "?").charAt(0).toUpperCase()}
                             </div>
                           )}
                         </div>
                         <span className={cn("px-3 py-1 text-[10px] font-bold tracking-widest uppercase rounded-full",
                           member.role === "OWNER" ? "bg-primary text-primary-foreground" :
                           member.role === "ADMIN" ? "bg-forest/10 text-forest" :
                           "bg-secondary text-muted-foreground"
                         )}>
                           {member.role}
                         </span>
                      </div>

                      <div>
                        <p className="font-serif text-xl group-hover:text-primary transition-colors">{member.name || "Unnamed Member"}</p>
                        <p className="text-sm text-muted-foreground truncate">{member.email}</p>
                      </div>

                      <div className="grid grid-cols-2 gap-4 mt-6 pt-4 border-t border-border/40">
                         <div>
                           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground">Contributions</p>
                           <p className="font-medium">{member.stats.contributions}</p>
                         </div>
                         <div>
                           <p className="text-[10px] font-bold tracking-widest uppercase text-muted-foreground">Responsibilities</p>
                           <p className="font-medium">{member.stats.activeResponsibilities}</p>
                         </div>
                      </div>
                    </div>
                  </motion.div>
                </Link>
              ))}
              </div>
            )}
          </section>

          {invitations.length > 0 && (
            <section className="space-y-6">
              <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground flex items-center gap-2"><Mail className="h-4 w-4" /> Pending Invitations</h2>
              <div className="space-y-3">
                {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                {invitations.map((invite: any) => (
                  <div key={invite.id} className="group flex items-center justify-between p-4 bg-background border border-border/50 rounded-2xl shadow-sm hover:shadow-md hover:border-primary/30 transition-all duration-300">
                     <div className="flex-1 min-w-0 pr-4">
                        <div className="flex items-center gap-3">
                          <p className="font-medium text-sm">{invite.email || "Invite Link"}</p>
                          <span className="px-2 py-0.5 rounded-full bg-secondary text-[10px] font-bold tracking-widest uppercase text-muted-foreground">{invite.role}</span>
                          <span className={cn("px-2 py-0.5 rounded-full text-[10px] font-bold tracking-widest uppercase",
                            invite.status === "PENDING" ? "bg-amber-500/10 text-amber-600" :
                            invite.status === "ACCEPTED" ? "bg-forest/10 text-forest" :
                            "bg-destructive/10 text-destructive"
                          )}>{invite.status}</span>
                        </div>
                        <p className="text-xs text-muted-foreground mt-1">Code: <span className="font-mono text-foreground">{invite.code}</span> • Expires {new Date(invite.expiresAt).toLocaleDateString()}</p>
                     </div>

                     <div className="flex items-center gap-2">
                        {invite.status === "PENDING" && (
                          <>
                            <Button 
                              variant="outline" 
                              size="sm" 
                              className="h-8 rounded-lg text-xs hidden sm:flex"
                              onClick={() => copyToClipboard(invite.code)}
                            >
                              {copiedCode === invite.code ? <Check className="h-3.5 w-3.5 mr-1" /> : <Copy className="h-3.5 w-3.5 mr-1" />}
                              Copy Code
                            </Button>
                            <Button 
                              variant="ghost" 
                              size="sm" 
                              className="h-8 w-8 p-0 text-destructive hover:text-destructive hover:bg-destructive/10 rounded-lg"
                              onClick={() => handleRevoke(invite.id)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </>
                        )}
                     </div>
                  </div>
                ))}
              </div>
            </section>
          )}

        </div>

        {/* Right Column: Roles & Activity */}
        <div className="space-y-12">
           <section className="bg-card border border-border/50 rounded-[2rem] p-6 sm:p-8 shadow-sm">
             <div className="flex items-center gap-2 mb-6">
               <Shield className="h-5 w-5 text-primary" />
               <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Roles & Permissions</h3>
             </div>

             <div className="space-y-6">
               <div>
                 <div className="flex items-center gap-2 mb-1">
                   <span className="px-2 py-0.5 text-[10px] font-bold tracking-widest uppercase bg-primary text-primary-foreground rounded">Owner</span>
                 </div>
                 <p className="text-xs text-muted-foreground">Full control. Can delete home, manage billing, and transfer ownership.</p>
               </div>
               <div>
                 <div className="flex items-center gap-2 mb-1">
                   <span className="px-2 py-0.5 text-[10px] font-bold tracking-widest uppercase bg-forest/10 text-forest rounded">Admin</span>
                 </div>
                 <p className="text-xs text-muted-foreground">Can invite members, manage spaces, and edit content.</p>
               </div>
               <div>
                 <div className="flex items-center gap-2 mb-1">
                   <span className="px-2 py-0.5 text-[10px] font-bold tracking-widest uppercase bg-secondary text-muted-foreground rounded">Member</span>
                 </div>
                 <p className="text-xs text-muted-foreground">Can view and add content (assets, expenses, maintenance).</p>
               </div>
               <div>
                 <div className="flex items-center gap-2 mb-1">
                   <span className="px-2 py-0.5 text-[10px] font-bold tracking-widest uppercase border border-border/50 text-muted-foreground rounded">Guest</span>
                 </div>
                 <p className="text-xs text-muted-foreground">View only access. Cannot modify data.</p>
               </div>
             </div>
           </section>

           <section className="bg-card border border-border/50 rounded-[2rem] p-6 sm:p-8 shadow-sm">
             <div className="flex items-center gap-2 mb-8">
               <Activity className="h-5 w-5 text-muted-foreground" />
               <h3 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Recent Household Activity</h3>
             </div>
             {recentActivity.length > 0 ? (
               <Timeline>
                 {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                 {recentActivity.map((act: any, i: number) => (
                   <TimelineItem
                     key={act.id}
                     icon={Clock}
                     title={act.type.replace(/_/g, ' ')}
                     description={act.description}
                     time={new Date(act.createdAt).toLocaleDateString()}
                     isLast={i === recentActivity.length - 1}
                   />
                 ))}
               </Timeline>
             ) : (
               <p className="text-sm text-muted-foreground">No recent activity.</p>
             )}
           </section>
        </div>
      </div>

      {/* Invite Modal (Simulated) */}
      <AnimatePresence>
        {inviteModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-background/80 backdrop-blur-sm" onClick={() => setInviteModalOpen(false)} />
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="relative bg-card border border-border/50 shadow-xl rounded-3xl w-full max-w-md p-6 sm:p-8">
              <h2 className="text-2xl font-serif text-primary mb-2">Invite Member</h2>
              <p className="text-sm text-muted-foreground mb-6">Send an invitation code to add someone to this household.</p>

              <form onSubmit={handleInvite} className="space-y-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium pl-1">Email Address (Optional)</label>
                  <input type="email" value={inviteEmail} onChange={e => setInviteEmail(e.target.value)} className="w-full h-12 px-4 bg-background border border-border/60 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20 transition-all" placeholder="name@example.com" />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium pl-1">Role</label>
                  <select value={inviteRole} onChange={e => setInviteRole(e.target.value)} className="w-full h-12 px-4 bg-background border border-border/60 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20 transition-all">
                    <option value="ADMIN">Admin</option>
                    <option value="MEMBER">Member</option>
                    <option value="GUEST">Guest</option>
                  </select>
                </div>

                <div className="pt-4 flex gap-3">
                  <Button type="button" variant="ghost" onClick={() => setInviteModalOpen(false)} className="flex-1 rounded-xl h-12">Cancel</Button>
                  <Button type="submit" disabled={inviting} className="flex-1 rounded-xl h-12 shadow-float bg-primary text-primary-foreground">
                    {inviting ? "Generating..." : "Generate Code"}
                  </Button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

    </div>
  );
}

