import { prisma } from "@/lib/prisma";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { ModuleSkeleton } from "@/components/ui/module-skeleton";
import { EmptyState } from "@/components/ui/empty-state";
import { EmptyMoneyIllustration } from "@/components/ui/illustrations";
import { MoneyDashboardClient } from "./components/money-dashboard-client";

export const dynamic = "force-dynamic";

export default async function MoneyPage() {
  const cookieStore = await cookies();
  const homeId = cookieStore.get("homeId")?.value;

  if (!homeId) {
    redirect("/select-home");
  }

  // Efficient aggregate queries
  const allExpenses = await prisma.expense.findMany({
    where: { homeId },
    include: {
      space: { select: { id: true, name: true } },
      asset: { select: { id: true, name: true } },
      maintenance: { select: { id: true, title: true } }
    },
    orderBy: { expenseDate: "desc" }
  });

  if (allExpenses.length === 0) {
    return (
      <div className="pt-24">
        <EmptyState
          illustration={<EmptyMoneyIllustration />}
          title="No financial history yet."
          description="Start tracking expenses, maintenance costs, and home investments to see where your money goes."
          actionLabel="Log Expense"
          actionHref="/money/create"
        />
      </div>
    );
  }

  return (
    <MoneyDashboardClient 
      initialExpenses={allExpenses} 
    />
  );
}

"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Space, Asset, Activity } from "@/lib/generated/prisma/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { 
  Package, FileText, Wrench, 
  Camera, StickyNote, Upload
} from "lucide-react";
import { Section } from "@/components/layout/section";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { ConnectedHomeGraph, GraphNode } from "@/components/graph/connected-home-graph";
import { useRecentStore } from "@/store/recent-store";
import { useEffect } from "react";

type SpaceWithRelations = Space & {
  assets: Asset[];
  activities: Activity[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  documents?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  maintenance?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  expenses?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  createdBy?: any;
};

interface SpaceDetailClientProps {
  space: SpaceWithRelations;
  relationshipsPanel?: React.ReactNode;
}

const TABS = [
  { id: "overview", label: "Overview" },
  { id: "assets", label: "Assets" },
  { id: "documents", label: "Documents" },
  { id: "care", label: "Care & Maintenance" },
  { id: "photos", label: "Photos" },
];

export function SpaceDetailClient({ space, relationshipsPanel }: SpaceDetailClientProps) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [activeTab, setActiveTab] = useState<any>("overview");
  const addRecent = useRecentStore((state) => state.addRecent);

  useEffect(() => {
    addRecent({
      id: space.id,
      title: space.name,
      type: "space",
      url: `/spaces/${space.id}`
    });
  }, [space.id, space.name, addRecent]);

  const expenses = space.expenses || [];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const totalInvestment = expenses.reduce((sum: number, exp: any) => sum + exp.amount, 0);
  const documents = space.documents || [];
  const maintenance = space.maintenance || [];

  // Calculate Real Health Data based on actual relations
  const hasAssets = space.assets.length > 0;

  const assetScore = Math.min(space.assets.length * 15, 60);
  const activityScore = Math.min(space.activities.length * 5, 40);
  const healthScore = hasAssets ? assetScore + activityScore : 0;

  // Connected Home Graph Data
  const centralNode: GraphNode = {
    id: space.id,
    type: "SPACE",
    name: space.name,
    subtitle: space.floor || "Unassigned Floor",
    link: `/spaces/${space.id}`
  };

  const satellites: GraphNode[] = [];
  if (space.createdBy) {
    satellites.push({
      id: space.createdBy.id,
      type: "MEMBER",
      name: space.createdBy.name || "Unknown",
      subtitle: "Creator",
      link: `/family/${space.createdBy.id}`
    });
  }
  space.assets.forEach((a: any) => satellites.push({
    id: a.id,
    type: "ASSET",
    name: a.name,
    subtitle: a.category,
    link: `/assets/${a.id}`
  }));
  documents.forEach((doc: any) => satellites.push({
    id: doc.id,
    type: "DOCUMENT",
    name: doc.title,
    link: `/vault/${doc.id}`
  }));
  maintenance.forEach((m: any) => satellites.push({
    id: m.id,
    type: "MAINTENANCE",
    name: m.title,
    link: `/care/${m.id}`
  }));
  expenses.forEach((e: any) => satellites.push({
    id: e.id,
    type: "EXPENSE",
    name: e.title,
    subtitle: `${e.currency} ${e.amount}`,
    link: `/money/${e.id}`
  }));

  return (
    <div className="space-y-10">

      {/* Connected Home Section */}
      <section className="space-y-6 pt-6">
        <h2 className="text-xl font-serif tracking-tight text-primary">Connected Home</h2>
        <ConnectedHomeGraph centralNode={centralNode} satellites={satellites} />
      </section>

      {/* TABS NAVIGATION */}
      <div className="sticky top-20 z-40 bg-background/80 backdrop-blur-xl border-b border-border/40 pb-0 pt-4 -mx-6 px-6 lg:-mx-12 lg:px-12">
        <div className="flex space-x-8 overflow-x-auto scrollbar-hide">
