"use client";

import { Shield, Search, FileText, ShieldAlert } from "lucide-react";
import { ModuleSkeleton } from "@/components/ui/module-skeleton";
import { PageHeader } from "@/components/layout/page-header";
import { EmptyState } from "@/components/ui/empty-state";
import { EmptyVaultIllustration } from "@/components/ui/illustrations";
import { motion } from "framer-motion";
import { Card } from "@/components/ui/card";
import { useHome } from "@/components/providers/home-provider";
import { useOnboarding } from "@/hooks/use-onboarding";
import { useQuery } from "@tanstack/react-query";
import { DocumentCard } from "./components/document-card";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

const SMART_CATEGORIES = [
  "Property", "Identity", "Insurance", "Bills", 
  "Warranty", "Manuals", "Medical", "Education", 
  "Finance", "Legal", "Other"
];

export default function VaultPage() {
  const { activeHome } = useHome();
  const { completion } = useOnboarding();
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const { data: documents, isLoading } = useQuery({
    queryKey: ["documents", activeHome?.id, searchQuery, activeCategory],
    queryFn: async () => {
      if (!activeHome?.id) return [];
      let url = "/api/documents?";
      if (searchQuery) url += `q=${encodeURIComponent(searchQuery)}&`;
      if (activeCategory) url += `category=${encodeURIComponent(activeCategory)}`;
      const res = await fetch(url, { headers: { "x-home-id": activeHome.id } });
      if (!res.ok) throw new Error("Failed to fetch documents");
      return res.json();
    },
    enabled: !!activeHome?.id,
  });

  // Derived sections
  const recentDocuments = documents?.slice(0, 8) || [];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const expiringDocuments = documents?.filter((d: any) => {
    if (!d.expiryDate) return false;
    const expiry = new Date(d.expiryDate);
    const now = new Date();
    const diffDays = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays <= 30;
  }) || [];

  return (
    <motion.div 
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8, ease: "easeOut" }}
      className="max-w-[1400px] mx-auto px-6 lg:px-12 pt-12 pb-32 space-y-10"
    >
      <PageHeader
        title="Digital Vault."
        description="The memory system of your home. Secure, connected, and intelligent."
        actions={
          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative flex-1 md:w-64 lg:w-80">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground/60" />
              <input 
                type="text" 
                placeholder="Search title, category, tags..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full h-12 pl-12 pr-4 rounded-2xl bg-background border border-border/60 focus-visible:outline-none focus-visible:border-primary/50 focus-visible:ring-2 focus-visible:ring-primary/20 transition-all text-sm hover:border-border placeholder:text-muted-foreground"
              />
            </div>
            <Button onClick={() => router.push("/vault/upload")} className="h-12 rounded-2xl px-6 shadow-sm hidden sm:flex">
              Upload Document
            </Button>
          </div>
        }
      />

      {documents?.length === 0 && !searchQuery && !activeCategory ? (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
        >
          <EmptyState
            illustration={<EmptyVaultIllustration />}
            title="The Vault is secure but empty."
            description="Upload warranties, receipts, manuals, and important home documents to keep them safe and organized."
            actionLabel="Upload Document"
            onAction={() => router.push("/vault/upload")}
          />
        </motion.div>
      ) : (
        <div className="space-y-16">

          {/* Smart Categories */}
          <section className="space-y-6">
             <div className="flex items-center justify-between">
               <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">Smart Categories</h2>
               {activeCategory && (
                 <button onClick={() => setActiveCategory(null)} className="text-xs font-medium text-primary">Clear Filter</button>
               )}
             </div>
             <div className="flex flex-wrap gap-3">
               {SMART_CATEGORIES.map(category => {
                 // eslint-disable-next-line @typescript-eslint/no-explicit-any
                 const count = documents?.filter((d: any) => d.category === category).length || 0;
                 const isActive = activeCategory === category;
                 return (
                   <button
                     key={category}
                     onClick={() => setActiveCategory(isActive ? null : category)}
                     className={cn(
                       "px-5 py-3 rounded-2xl border transition-all duration-300 text-sm font-medium flex items-center gap-2",
                       isActive 
                        ? "bg-primary text-primary-foreground border-primary shadow-sm" 
                        : "bg-card border-border/50 text-muted-foreground hover:bg-secondary/40 hover:text-foreground"
                     )}
                   >
                     {category} 
                     <span className={cn(
                       "text-[10px] py-0.5 px-2 rounded-full",
                       isActive ? "bg-black/20 text-white" : "bg-secondary text-muted-foreground"
                     )}>
                       {count}
                     </span>
                   </button>
                 );
               })}
             </div>
          </section>

          {/* Expiring Documents (if any) */}
          {expiringDocuments.length > 0 && !activeCategory && !searchQuery && (
            <section className="space-y-6">
              <div className="flex items-center gap-2 text-amber-500">
                <ShieldAlert className="h-4 w-4" />
                <h2 className="text-sm font-bold tracking-widest uppercase">Action Required</h2>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                {expiringDocuments.map((doc: any) => (
                  <DocumentCard key={doc.id} document={doc} />
                ))}
              </div>
            </section>
          )}

          {/* Recent/Filtered Documents */}
          <section className="space-y-6">
             <div className="flex items-center justify-between">
               <h2 className="text-sm font-bold tracking-widest uppercase text-muted-foreground">
                 {searchQuery ? "Search Results" : activeCategory ? `${activeCategory} Documents` : "Recent Documents"}
               </h2>
             </div>

             {isLoading ? (
                <div className="h-64 flex flex-col items-center justify-center text-muted-foreground/50 gap-4">
                   <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                   <p className="text-sm">Accessing memory...</p>
                </div>
             ) : documents?.length === 0 ? (
                <div className="h-64 flex flex-col items-center justify-center text-muted-foreground gap-2 border-2 border-dashed border-border/60 rounded-3xl bg-secondary/10">
                  <FileText className="h-8 w-8 opacity-20 mb-2" />
                  <p className="font-medium">No documents found.</p>
                  <p className="text-sm opacity-60">Try adjusting your search or category filter.</p>
                </div>
             ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                 {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                 {(searchQuery || activeCategory ? documents : recentDocuments)?.map((doc: any) => (
                   <DocumentCard key={doc.id} document={doc} />
                 ))}
               </div>
             )}
          </section>

        </div>
      )}

      {/* Mobile FAB */}
      <div className="fixed bottom-6 right-6 sm:hidden z-40">
        <Button onClick={() => router.push("/vault/upload")} size="icon" className="h-14 w-14 rounded-full shadow-float bg-primary text-primary-foreground">
          <FileText className="h-6 w-6" />
        </Button>
      </div>
    </motion.div>
  );
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { withHomeAuth, AuthenticatedRequest } from "@/lib/api-auth";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const GET = withHomeAuth(async (req: AuthenticatedRequest, context: any) => {
  try {
    const resolvedParams = await Promise.resolve(context.params);
    const homeId = resolvedParams.homeId;

    if (homeId !== req.home!.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    }

    // 1. Fetch raw data for metrics
    const [
      spacesCount,
      assetsCount,
      membershipsCount,
      recentActivities,
      recentAssets,
      newestSpaces,
      pendingInvitations,
      newestMembers,
      documentsCount,
      maintenanceCount,
      expensesCount,
      allSpaces,
      allAssets
    ] = await Promise.all([
      prisma.space.count({ where: { homeId, archived: false } }),
      prisma.asset.count({ where: { homeId, archived: false } }),
      prisma.membership.count({ where: { homeId } }),
      prisma.activity.findMany({
        where: { homeId },
        orderBy: { createdAt: "desc" },
        take: 20,
        include: {
          user: { select: { name: true, avatar: true } },
          space: { select: { name: true } },
        }
      }),
      prisma.asset.findMany({
        where: { homeId, archived: false },
        orderBy: { createdAt: "desc" },
        take: 3,
        include: { space: { select: { name: true } } }
      }),
      prisma.space.findMany({
        where: { homeId, archived: false },
        orderBy: { createdAt: "desc" },
        take: 3,
      }),
      prisma.invitation.findMany({
        where: { homeId, status: "PENDING" },
        orderBy: { createdAt: "desc" }
      }),
      prisma.membership.findMany({
        where: { homeId },
        orderBy: { createdAt: "desc" },
        take: 3,
        include: { user: { select: { name: true, avatar: true } } }
      }),
      prisma.document.count({ where: { homeId } }),
      prisma.maintenance.count({ where: { homeId } }),
      prisma.expense.count({ where: { homeId } }),
      prisma.space.findMany({
        where: { homeId, archived: false },
        include: { _count: { select: { assets: true, documents: true, maintenance: true, expenses: true } } }
      }),
      prisma.asset.findMany({
        where: { homeId, archived: false },
        include: { _count: { select: { documents: true, maintenance: true, expenses: true } } }
      })
    ]);

    // Graph Nodes
    const graphNodes = [
      ...allSpaces.map(s => ({
        id: s.id, type: "SPACE", name: s.name, subtitle: "Space", link: `/spaces/${s.id}`,
        connections: s._count.assets + s._count.documents + s._count.maintenance + s._count.expenses
      })),
      ...allAssets.map(a => ({
        id: a.id, type: "ASSET", name: a.name, subtitle: a.category || "Asset", link: `/assets/${a.id}`,
        connections: a._count.documents + a._count.maintenance + a._count.expenses + (a.spaceId ? 1 : 0)
      }))
    ].sort((a, b) => b.connections - a.connections).slice(0, 10).map(({ connections, ...rest }) => rest);

    // 2. Home Completion Progress (Setup Journey)
    const hasSpaces = spacesCount > 0;
    const hasAssets = assetsCount > 0;
    const hasDocuments = documentsCount > 0;
    const hasMaintenance = maintenanceCount > 0;
    const hasExpenses = expensesCount > 0;
    const hasInvitedFamily = membershipsCount > 1;

    const isComplete = hasSpaces && hasAssets && hasDocuments && hasMaintenance && hasExpenses && hasInvitedFamily;

    const completion = {
      hasSpaces,
      hasAssets,
      hasDocuments,
      hasMaintenance,
      hasExpenses,
      hasInvitedFamily,
      isComplete
    };

    // 3. Home Health Engine
    // Deterministic logic based on real data
    let healthScore = 0;
    const isLearning = spacesCount === 0 && assetsCount === 0;

    if (!isLearning) {
      const spaceOrgScore = spacesCount > 0 ? 30 : 0; // Out of 30
      const assetCovScore = assetsCount > 0 ? 40 : 0; // Out of 40
      const familyScore = membershipsCount > 1 ? 30 : 10; // Out of 30

      healthScore = spaceOrgScore + assetCovScore + familyScore;
    }

    // 4. Insights Generation
    const insights: string[] = [];
    if (spacesCount > 0 && assetsCount === 0) {
      insights.push(`You have created ${spacesCount} space${spacesCount > 1 ? 's' : ''}, but haven't added any assets yet.`);
    } else if (assetsCount > 0) {
      insights.push(`You are actively tracking ${assetsCount} digital asset${assetsCount > 1 ? 's' : ''}.`);
    }

    if (membershipsCount === 1) {
      insights.push("Invite family members to collaborate on home management.");
    } else {
      insights.push(`${membershipsCount} members are helping manage your home.`);
    }

    if (recentAssets.length > 0) {
      insights.push(`Most recently added asset: ${recentAssets[0].name}.`);
    }

    return NextResponse.json({
      feed: recentActivities,
      health: {
        score: healthScore,
        isLearning,
        categories: {
          spaceOrganization: spacesCount > 0 ? 100 : 0,
          assetCoverage: assetsCount > 0 ? 100 : 0,
          familyParticipation: membershipsCount > 1 ? 100 : 33,
        }
      },
      insights,
      today: {
        recentAssets,
        newestSpaces,
        pendingInvitations,
        newestMembers,
      },
      completion,
      graphNodes,
    });
  } catch (error) {
    console.error("Failed to fetch dashboard data:", error);
    return NextResponse.json(
      { error: "Failed to fetch dashboard data" },
      { status: 500 }
    );
  }
});

